def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Compare near-solid horizontal bars of the same color.
    bars = []
    for r, row in enumerate(grid):
        fg = [v for v in row if v != bg]
        if len(fg) >= w // 2 and len(set(fg)) == 1:
            bars.append((r, fg[0]))

    for i in range(len(bars)):
        r1, c1 = bars[i]
        for j in range(i + 1, len(bars)):
            r2, c2 = bars[j]
            if c1 != c2:
                continue
            diffs = [c for c in range(w) if grid[r1][c] != grid[r2][c]]
            if diffs and len(diffs) <= w // 2:
                for c in diffs:
                    if grid[r1][c] == bg and grid[r2][c] != bg:
                        out[r1][c] = 1
                    if grid[r2][c] == bg and grid[r1][c] != bg:
                        out[r2][c] = 1

    # Find repeated multi-row patterns and mark background-colored deviations.
    for size in range(2, min(8, h) + 1):
        area = size * w
        limit = max(1, area // 12)
        min_fg = max(3, area * 12 // 100)
        for a in range(h - size + 1):
            for b in range(a + size, h - size + 1):
                fg_a = sum(grid[r][c] != bg
                           for r in range(a, a + size) for c in range(w))
                fg_b = sum(grid[r][c] != bg
                           for r in range(b, b + size) for c in range(w))
                if min(fg_a, fg_b) < min_fg:
                    continue

                diffs = []
                for dr in range(size):
                    for c in range(w):
                        if grid[a + dr][c] != grid[b + dr][c]:
                            diffs.append((dr, c))
                if not diffs or len(diffs) > limit:
                    continue

                for dr, c in diffs:
                    va, vb = grid[a + dr][c], grid[b + dr][c]
                    if va == bg and vb != bg:
                        out[a + dr][c] = 1
                    elif vb == bg and va != bg:
                        out[b + dr][c] = 1

    return out
