def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Group consecutive rows containing any non-background cells.
    runs = []
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(v != bg for v in grid[r]):
            r += 1
        runs.append((start, r))

    # Repeated patterns can differ where background cells replace pattern
    # cells; mark those differing background cells.
    for i, (a0, a1) in enumerate(runs):
        for b0, b1 in runs[i + 1:]:
            if a1 - a0 != b1 - b0:
                continue
            for da in range(a1 - a0):
                for c in range(w):
                    va = grid[a0 + da][c]
                    vb = grid[b0 + da][c]
                    if va != vb:
                        if va == bg and vb != bg:
                            out[a0 + da][c] = 1
                        elif vb == bg and va != bg:
                            out[b0 + da][c] = 1

    return out
